export class Failure extends Error {
  constructor(code, message) {
    super(message)
    this.code = code
  }
}

export function usageError() {
  return new Failure(2, 'error: usage: cli.js waves|explain|pack <workers>')
}

export function fail(message) {
  return new Failure(2, message)
}

export function cycleError(names) {
  return new Failure(3, `error: cycle: ${names.join(' -> ')}`)
}
"}

