import { Graph } from './graph.js'

const NAME = /^[A-Za-z0-9_.-]+$/
const DIGITS = /^[0-9]+$/

export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function checkName(name, lineNo) {
  if (!NAME.test(name)) throw fail(`error: line ${lineNo}: invalid task name ${name}`)
}

// Parses the directives of a build graph, validating every line as it goes.
export function parseGraph(input) {
  const lines = splitLines(input)
  const costs = new Map() // declared name -> cost
  const edges = [] // [from, to] in input order
  const referenced = [] // names used by dep lines, in first-use order
  const seenReference = new Set()

  const reference = (name) => {
    if (!seenReference.has(name)) {
      seenReference.add(name)
      referenced.push(name)
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    const lineNo = i + 1
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)

    if (words[0] === 'task') {
      if (words.length !== 3) throw fail(`error: line ${lineNo}: expected task <name> <cost>`)
      const [, name, cost] = words
      checkName(name, lineNo)
      if (!DIGITS.test(cost)) throw fail(`error: line ${lineNo}: cost must be a non-negative integer`)
      if (costs.has(name)) throw fail(`error: line ${lineNo}: task ${name} is declared twice`)
      costs.set(name, Number(cost))
    } else if (words[0] === 'dep') {
      if (words.length < 3) throw fail(`error: line ${lineNo}: expected dep <name> <dependency>...`)
      for (let w = 1; w < words.length; w++) checkName(words[w], lineNo)
      const target = words[1]
      reference(target)
      for (let w = 2; w < words.length; w++) {
        reference(words[w])
        edges.push([target, words[w]])
      }
    } else {
      throw fail(`error: line ${lineNo}: unknown directive ${words[0]}`)
    }
  }

  for (const name of referenced) {
    if (!costs.has(name)) throw fail(`error: unknown task ${name}`)
  }

  const graph = new Graph()
  for (const name of [...costs.keys()].sort()) graph.addTask(name, costs.get(name))
  for (const [from, to] of edges) graph.addEdge(from, to)
  return graph
}
"}

