{"file_path":"src/graph.js","content":"import { cycleError } from './errors.js'

// A build graph: tasks with costs and dependency edges.
export class Graph {
  constructor() {
    this.costs = new Map() // name -> cost
    this.deps = new Map() // name -> Set of dependencies
    this.dependents = new Map() // name -> Set of tasks depending on it
  }

  addTask(name, cost) {
    this.costs.set(name, cost)
    this.deps.set(name, new Set())
    this.dependents.set(name, new Set())
  }

  addEdge(from, to) {
    this.deps.get(from).add(to)
    this.dependents.get(to).add(from)
  }

  // Task names in ascending order.
  names() {
    return [...this.costs.keys()].sort()
  }

  sortedDeps(name) {
    return [...this.deps.get(name)].sort()
  }

  // The first cycle a depth-first search finds, or null. Iterative, so that
  // very deep graphs cannot overflow the call stack.
  findCycle() {
    const OPEN = 1
    const DONE = 2
    const state = new Map()

    for (const root of this.names()) {
      if (state.get(root) === DONE) continue
      const path = [root]
