{"file_path":"src/commands.js","content":"// Rendering of the three commands. Each returns the full stdout text.

export function waves(graph) {
  const { depth, total } = graph.schedule()
  const byWave = []
  for (const name of graph.names()) {
    const d = depth.get(name)
    while (byWave.length <= d) byWave.push([])
    byWave[d].push(name)
  }
  const lines = byWave.map((names, index) => `wave ${index}: ${names.join(' ')}`)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

export function explain(graph) {
  const { depth, start, finish, total } = graph.schedule()
  const lines = graph.names().map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

export function pack(graph, workers) {
  const priority = graph.priorities()
  const names = graph.names()
  const free = new Array(workers).fill(0) // when each worker is next free
  const ran = Array.from({ length: workers }, () => [])
  const finished = new Map()
  const done = new Set()
  let remaining = names.length
  let now = 0

  const ready = (name) => {
    for (const dep of graph.deps.get(name)) {
      if (!finished.has(dep) || finished.get(dep) > now) return false
    }
    return true
  }

  while (remaining > 0) {
    for (;;) {
      let worker = -1
      for (let w = 0; w < workers; w++) {
        if (free[w] <= now) {
          worker = w
          break
        }
      }
      if (worker === -1) break

      let chosen = null
      for (const name of names) {
        if (done.has(name)) continue
        if (!ready(name)) continue
        if (chosen === null || priority.get(name) > priority.get(chosen)) chosen = name
      }
      if (chosen === null) break

      const start = now
      const finish = start + graph.costs.get(chosen)
      ran[worker].push(`${chosen}@${start}-${finish}`)
      free[worker] = finish
      finished.set(chosen, finish)
      done.add(chosen)
      remaining--
    }

    if (remaining === 0) break
    let next = Infinity
    for (const time of free) if (time > now && time < next) next = time
    if (next === Infinity) break
    now = next
  }

  const lines = []
  let makespan = 0
  for (const value of finished.values()) if (value > makespan) makespan = value
  for (let w = 0; w < workers; w++) {
    lines.push(ran[w].length === 0 ? `worker ${w}:` : `worker ${w}: ${ran[w].join(' ')}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}
"}

