    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const { command, workers } = parseArgs(process.argv.slice(2))
  const graph = parseGraph(await readStdin())
  graph.assertAcyclic()
  const output =
    command === 'waves'
      ? commands.waves(graph)
      : command === 'explain'
        ? commands.explain(graph)
        : commands.pack(graph, workers)
  process.stdout.write(output)
}

main().catch((error) => {
  if (error instanceof Failure) {
    process.stderr.write(error.message + '\n')
    process.exitCode = error.code
  } else {
    process.stderr.write(`error: ${error && error.message ? error.message : error}\n`)
    process.exitCode = 1
  }
})

