export function pack(graph, workers) {
  const priority = graph.priorities()
  const names = graph.names()
  // Only the first `names.length` workers can ever run anything, because a
  // task always goes to the free worker with the smallest index.
  const tracked = Math.min(workers, Math.max(names.length, 1))
  const ran = Array.from({ length: tracked }, () => [])

  // Tasks whose dependencies have all finished, ordered by the scheduling rule.
  const available = new Heap((a, b) =>
    priority.get(a) !== priority.get(b) ? priority.get(a) > priority.get(b) : a < b,
  )
  // Tasks that became ready at a later instant, ordered by that instant.
  const upcoming = new Heap((a, b) => a.at < b.at)
  const idle = new Heap((a, b) => a < b) // free worker indices
  const busy = new Heap((a, b) => (a.at !== b.at ? a.at < b.at : a.worker < b.worker))

  const pending = new Map() // unfinished dependencies left
  const readyAt = new Map() // instant at which the last dependency finishes
  for (const name of names) {
    const count = graph.deps.get(name).size
    pending.set(name, count)
    readyAt.set(name, 0)
    if (count === 0) available.push(name)
  }
  for (let w = 0; w < tracked; w++) idle.push(w)

  let remaining = names.length
  let makespan = 0
  let now = 0

  while (remaining > 0) {
    while (busy.size > 0 && busy.peek().at <= now) idle.push(busy.pop().worker)
    while (upcoming.size > 0 && upcoming.peek().at <= now) available.push(upcoming.pop().name)

    while (idle.size > 0 && available.size > 0) {
      const worker = idle.pop()
      const name = available.pop()
      const finish = now + graph.costs.get(name)
      ran[worker].push(`${name}@${now}-${finish}`)
      if (finish > makespan) makespan = finish
      remaining--

      for (const next of graph.dependents.get(name)) {
        if (readyAt.get(next) < finish) readyAt.set(next, finish)
        const left = pending.get(next) - 1
        pending.set(next, left)
        if (left === 0) upcoming.push({ name: next, at: readyAt.get(next) })
      }
      if (finish <= now) idle.push(worker)
      else busy.push({ worker, at: finish })
      while (upcoming.size > 0 && upcoming.peek().at <= now) available.push(upcoming.pop().name)
    }

    if (remaining === 0 || busy.size === 0) break
    now = busy.peek().at
  }

  const lines = []
  for (let w = 0; w < workers; w++) {
    const run = w < tracked ? ran[w] : []
    lines.push(run.length === 0 ? `worker ${w}:` : `worker ${w}: ${run.join(' ')}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'

